import Foundation
struct DashboardPayload:Decodable{struct Month:Decodable{let income:String;let expense:String};let month:Month}
@MainActor final class DashboardViewModel:ObservableObject{@Published var recent:[FinanceTransaction]=[];@Published var income="—";@Published var expense="—";@Published var net="—";@Published var isLoading=false;let container:AppContainer;init(container:AppContainer){self.container=container}func load(bookId:UUID?)async{guard let bookId else{return};isLoading=true;defer{isLoading=false};recent=(try? await container.transactions.recent(bookId:bookId,limit:10)) ?? [];if let payload:DashboardPayload=try? await container.api.get("reports/dashboard",query:[.init(name:"bookId",value:bookId.uuidString)]),let incoming=Decimal(string:payload.month.income,locale:Locale(identifier:"en_US_POSIX")),let outgoing=Decimal(string:payload.month.expense,locale:Locale(identifier:"en_US_POSIX")){income=payload.month.income;expense=payload.month.expense;net=NSDecimalNumber(decimal:incoming-outgoing).stringValue}}}
